#include <iostream>
#include <string>

class BaseAccount {
public:
    explicit BaseAccount(double bal) : balance{bal} {}
    double getBalance() const { return balance; }
private:
    double balance;
};

class SavingsAccount : public BaseAccount {
public:
    SavingsAccount(double bal, double rate) : BaseAccount{bal}, interestRate{rate} {}
    double getInterestRate() const { return interestRate; }
private:
    double interestRate;
};

int main() {
    SavingsAccount savings{1000.0, 0.05};
    BaseAccount* basePtr = &savings;

    // Allowed: getBalance is declared in BaseAccount
    std::cout << "BaseAccount pointer sees balance: " << basePtr->getBalance() << "\n";

    // Downcasting via static_cast to access derived-only member
    auto* savingsPtr = static_cast<SavingsAccount*>(basePtr);
    std::cout << "Downcasted pointer sees interest rate: " << savingsPtr->getInterestRate() << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default; // Best practice: virtual destructor for polymorphic bases
    virtual void draw() const {
        std::cout << "Drawing generic Shape\n";
    }
};

class Circle : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing Circle\n";
    }
};

class Rectangle : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing Rectangle\n";
    }
};

int main() {
    Circle circle;
    Rectangle rectangle;

    // Direct call via object name: static binding
    circle.draw();

    // Polymorphic calls via base-class pointer and reference: dynamic binding
    Shape* shapePtr = &circle;
    shapePtr->draw(); // calls Circle::draw dynamically

    shapePtr = &rectangle;
    shapePtr->draw(); // calls Rectangle::draw dynamically

    Shape& shapeRef = circle;
    shapeRef.draw();  // calls Circle::draw dynamically

    return 0;
}
